class NextBlendedHover{static instances=[];constructor(element){Object.assign(this,{element,frontTitle:element.querySelector(".dan-blended-hover__title--front"),backTitle:element.querySelector(".dan-blended-hover__title--back"),duration:parseFloat(element.getAttribute("data-duration")),ease:element.getAttribute("data-easing"),eventListeners:[]});this.initialize()}
initialize(){this.updateContent();this.createSplitText();this.setupCharacters();this.createAnimation();this.setupEventListeners()}
updateContent(){const content=this.frontTitle.getAttribute('data-content');if(content){this.frontTitle.innerHTML=content;this.backTitle.innerHTML=content}}
createSplitText(){if(this.frontSplit)this.frontSplit.revert();if(this.backSplit)this.backSplit.revert();this.frontSplit=new SplitText(this.frontTitle,{type:"words, chars",charsClass:"char"});this.backSplit=new SplitText(this.backTitle,{type:"words, chars",charsClass:"char"})}
setupCharacters(){this.frontOdd=this.frontTitle.querySelectorAll(".char:nth-child(odd)");this.frontEven=this.frontTitle.querySelectorAll(".char:nth-child(even)");this.backOdd=this.backTitle.querySelectorAll(".char:nth-child(odd)");this.backEven=this.backTitle.querySelectorAll(".char:nth-child(even)")}
createAnimation(){if(this.timeline){this.timeline.kill()}
this.timeline=gsap.timeline({paused:!0,defaults:{duration:this.duration,ease:this.ease}}).fromTo(this.frontOdd,{yPercent:100},{yPercent:0}).fromTo(this.frontEven,{yPercent:0},{yPercent:100},0).fromTo(this.backOdd,{yPercent:0},{yPercent:-100},0).fromTo(this.backEven,{yPercent:-100},{yPercent:0},0)}
setupEventListeners(){this.eventListeners.forEach(({element,type,listener})=>{element.removeEventListener(type,listener)});this.eventListeners=[];const onEnter=()=>this.timeline.restart();this.element.addEventListener("mouseenter",onEnter);this.eventListeners.push({element:this.element,type:"mouseenter",listener:onEnter})}
destroy(){if(this.timeline){this.timeline.kill()}
if(this.frontSplit){this.frontSplit.revert()}
if(this.backSplit){this.backSplit.revert()}
this.eventListeners.forEach(({element,type,listener})=>{element.removeEventListener(type,listener)});this.eventListeners=[];this.updateContent()}
static destroyAll(){NextBlendedHover.instances.forEach(instance=>instance.destroy());NextBlendedHover.instances=[]}}
const dancepad_blended_hover=()=>{NextBlendedHover.destroyAll();document.querySelectorAll(".dan-blended-hover").forEach(element=>{element.removeAttribute('data-flickering');NextBlendedHover.instances.push(new NextBlendedHover(element))})}